// Content.js
import React, { useState, useEffect } from 'react';
import './Content.css';
import Ahorro from '../MenuForms/Ahorro'; // Asegúrate de que la ruta es correcta

const Content = ({ user = {} }) => {
    const [activeTab, setActiveTab] = useState('inicio');
    const [initialForm, setInitialForm] = useState({});
    const [goalForm, setGoalForm] = useState({});
    const [saveForm, setSaveForm] = useState({});
    const [retireForm, setRetireForm] = useState({});

    useEffect(() => {
        if (user._id) {
            fetchFormData('initial', setInitialForm);
            fetchFormData('goals', setGoalForm);
            fetchFormData('save', setSaveForm);
            fetchFormData('retires', setRetireForm);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user._id]);

    const fetchFormData = async (formType, setFormState) => {
        try {
            const response = await fetch(`http://localhost:5000/api/forms/${formType}/get${capitalize(formType)}/${user._id}`);
            if (!response.ok) {
                throw new Error(`Error fetching ${formType} form data`);
            }
            const result = await response.json();
            setFormState(result);
        } catch (error) {
            console.error(`Error fetching ${formType} form data:`, error);
        }
    };

    const capitalize = (string) => string.charAt(0).toUpperCase() + string.slice(1);

    return (
        <div className="content-container">
            <div className="user-info">
                <h2>{user.Nombres ? `${user.Nombres} ${user.Apellidos}` : 'Nombre del Usuario'}</h2>
                <p>Correo Electrónico: {user.Correo || 'No disponible'}</p>
            </div>

            <div className="tabs" role="tablist">
                <button
                    role="tab"
                    aria-selected={activeTab === 'inicio'}
                    aria-controls="inicio-tab"
                    id="inicio-tab-button"
                    className={`tab-button ${activeTab === 'inicio' ? 'active' : ''}`}
                    onClick={() => setActiveTab('inicio')}
                >
                    Inicio
                </button>
                <button
                    role="tab"
                    aria-selected={activeTab === 'generarAhorro'}
                    aria-controls="generarAhorro-tab"
                    id="generarAhorro-tab-button"
                    className={`tab-button ${activeTab === 'generarAhorro' ? 'active' : ''}`}
                    onClick={() => setActiveTab('generarAhorro')}
                >
                    Generar Ahorro
                </button>
                <button
                    role="tab"
                    aria-selected={activeTab === 'planJubilacion'}
                    aria-controls="planJubilacion-tab"
                    id="planJubilacion-tab-button"
                    className={`tab-button ${activeTab === 'planJubilacion' ? 'active' : ''}`}
                    onClick={() => setActiveTab('planJubilacion')}
                >
                    Plan de Jubilación
                </button>
                <button
                    role="tab"
                    aria-selected={activeTab === 'metas'}
                    aria-controls="metas-tab"
                    id="metas-tab-button"
                    className={`tab-button ${activeTab === 'metas' ? 'active' : ''}`}
                    onClick={() => setActiveTab('metas')}
                >
                    Metas Largo/Corto Plazo
                </button>
            </div>

            <div className="tab-content">
                {activeTab === 'inicio' && (
                    <div className="tab-section" id="inicio-tab">
                        <h3>Formulario Inicial</h3>
                        <table>
                            <tbody>
                                <tr>
                                    <th>Salario:</th>
                                    <td>{initialForm.salary || 'No disponible'}</td>
                                </tr>
                                <tr>
                                    <th>Paga Servicios:</th>
                                    <td>{initialForm.paysServices ? 'Sí' : 'No'}</td>
                                </tr>
                                <tr>
                                    <th>Gastos Mensuales:</th>
                                    <td>{initialForm.monthlyExpenses || 'No disponible'}</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                )}
                {activeTab === 'generarAhorro' && (
                    <Ahorro userId={user._id} />
                )}
                {activeTab === 'planJubilacion' && (
                    <div className="tab-section" id="planJubilacion-tab">
                        <h3>Plan de Jubilación</h3>
                        <table>
                            <tbody>
                                <tr>
                                    <th>Plan de Jubilación:</th>
                                    <td>{retireForm.retirementPlan ? 'Sí' : 'No'}</td>
                                </tr>
                                <tr>
                                    <th>Persona Gastadora:</th>
                                    <td>{retireForm.spenderPerson ? 'Sí' : 'No'}</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                )}
                {activeTab === 'metas' && (
                    <div className="tab-section" id="metas-tab">
                        <h3>Metas Largo/Corto Plazo</h3>
                        <table>
                            <tbody>
                                <tr>
                                    <th>Meta a Corto Plazo:</th>
                                    <td>{goalForm.shortTerm ? 'Sí' : 'No'}</td>
                                </tr>
                                <tr>
                                    <th>Meta a Mediano Plazo:</th>
                                    <td>{goalForm.mediumTerm ? 'Sí' : 'No'}</td>
                                </tr>
                                <tr>
                                    <th>Meta a Largo Plazo:</th>
                                    <td>{goalForm.longTerm ? 'Sí' : 'No'}</td>
                                </tr>
                                <tr>
                                    <th>Presupuesto Mensual:</th>
                                    <td>{goalForm.monthlyBudget ? 'Sí' : 'No'}</td>
                                </tr>
                                <tr>
                                    <th>Tipo de Meta:</th>
                                    <td>{goalForm.goalType || 'No disponible'}</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Content;
